import{_ as a,o as s,c as o,a4 as n}from"./chunks/framework.BE47AOxC.js";const p=JSON.parse('{"title":"ADR-0066 — Pages multilingues : une page par langue, un arbre par langue","description":"Extrait de docs/adr/0066-pages-multilingues.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0066 — Pages multilingues : une page par langue, un arbre par langue","description":"Extrait de docs/adr/0066-pages-multilingues.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0066-pages-multilingues.md","filePath":"developpeurs/adr/0066-pages-multilingues.md"}'),t={name:"developpeurs/adr/0066-pages-multilingues.md"};function r(l,e,i,u,d,c){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0066--pages-multilingues--une-page-par-langue-un-arbre-par-langue" tabindex="-1">ADR-0066 — Pages multilingues : une page par langue, un arbre par langue <a class="header-anchor" href="#adr-0066--pages-multilingues--une-page-par-langue-un-arbre-par-langue" aria-label="Permalink to &quot;ADR-0066 — Pages multilingues : une page par langue, un arbre par langue {#adr-0066--pages-multilingues--une-page-par-langue-un-arbre-par-langue}&quot;">​</a></h1><p><strong>Date :</strong> 7 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a>, action « Pages multilingues et brouillon de page » (le brouillon a été livré par l&#39;ADR-0065) ; <a href="/teuthis-cms-distribution/developpeurs/adr/0025-multilinguisme-groupe-de-traduction">ADR-0025</a>, action « Front public : sélecteur de langue, routage par URL, repli sur la langue par défaut » ; lot 12 <strong>Complète :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0025-multilinguisme-groupe-de-traduction">ADR-0025</a> (groupes de traduction), <a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a> (adresses publiques, segments de langue), <a href="/teuthis-cms-distribution/developpeurs/adr/0064-page-d-accueil-et-descripteur-de-site">ADR-0064</a> (page d&#39;accueil, descripteur), <a href="/teuthis-cms-distribution/developpeurs/adr/0065-cycle-de-vie-des-pages">ADR-0065</a> (cycle de vie des pages)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Les contenus sont multilingues depuis l&#39;ADR-0025 : une version par langue, reliées par un groupe de traduction, chacune avec son adresse préfixée de la langue (<code>/en/actualites/music-day</code>, ADR-0034). Les <strong>pages</strong> du Page Builder, elles, n&#39;avaient pas de langue : une page n&#39;était servie que dans la langue par défaut de son site, la racine d&#39;une autre langue (<code>/en</code>) répondait 404 (ADR-0064, décision 5), et un site bilingue n&#39;avait aucun moyen de publier « À propos » en anglais. L&#39;ADR-0065 a livré le brouillon de page et laissé ouverte la moitié multilingue de l&#39;action de l&#39;ADR-0034.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p>Décisions du Product Owner, reprises telles quelles :</p><ol><li><strong>Une page par langue, reliées par un groupe de traduction, comme les contenus (ADR-0025).</strong> Chaque version a son slug, son titre, sa composition et <strong>son propre cycle de vie</strong> (ADR-0065) : on publie la version anglaise quand elle est relue, indépendamment de la française.</li><li><strong>Un arbre par langue.</strong> Une page anglaise a un parent anglais. « Traduire » une page dont le parent n&#39;a pas de version dans la langue cible la place à la racine de l&#39;arbre de cette langue.</li><li><strong>« Traduire en … »</strong> sur la fiche d&#39;une page crée la version cible <strong>en brouillon</strong>, avec une copie de la composition à retraduire. Pas d&#39;IA pour les pages.</li><li><strong>Site public</strong> : <code>/en</code> (segment de langue, ADR-0034 règle 3) sert la version anglaise de la page d&#39;accueil ; <code>hreflang</code> dans la résolution et le plan de site ; sélecteur de langue dans le front de démarrage (<code>apps/front</code>).</li></ol><h3 id="modèle-migration-0050_pages_multilinguespy" tabindex="-1">Modèle (migration <code>0050_pages_multilingues.py</code>) <a class="header-anchor" href="#modèle-migration-0050_pages_multilinguespy" aria-label="Permalink to &quot;Modèle (migration `0050_pages_multilingues.py`) {#modèle-migration-0050_pages_multilinguespy}&quot;">​</a></h3><ul><li><code>pages.locale VARCHAR(10) NOT NULL</code>, <strong>sans défaut</strong> : chaque voie de création la pose (langue par défaut du site si rien n&#39;est demandé), et une insertion qui l&#39;oublierait échoue au lieu de ranger la page dans une langue au hasard. <strong>Reprise</strong> : <code>sites.default_locale</code> du site de chaque page — avant cette migration, une page n&#39;était servie que dans cette langue-là.</li><li><code>pages.translation_group_id UUID NULL</code>, <strong>sans clé étrangère</strong> (ADR-0025, propriété 1) : identifiant partagé, aucun membre principal, <code>NULL</code> jusqu&#39;à la première traduction.</li><li>Unicité <code>(site_id, locale, slug)</code> à la place de <code>(site_id, slug)</code> : <code>/mairie</code> et <code>/en/mairie</code> sont deux adresses. Menée par <code>(site_id, locale)</code>, elle sert aussi d&#39;index au filtre de langue des lectures d&#39;arbre (plan du site, sœurs, recherche) — aucun index de plus n&#39;était nécessaire.</li><li>Index unique partiel <code>(translation_group_id, locale) WHERE translation_group_id IS NOT NULL</code> : une version par langue dans un groupe ; il sert aussi la lecture des membres d&#39;un groupe.</li><li><strong>Retour arrière refusé</strong> (<code>RuntimeError</code> au message explicite) s&#39;il existe une page hors de la langue par défaut de son site : le schéma précédent n&#39;a aucun logement pour elle. On ne détruit pas de contenu en silence ; l&#39;exploitant supprime ces versions, puis redescend.</li></ul><h3 id="règles-décriture-apppage_builderlocalespy" tabindex="-1">Règles d&#39;écriture (<code>app/page_builder/locales.py</code>) <a class="header-anchor" href="#règles-décriture-apppage_builderlocalespy" aria-label="Permalink to &quot;Règles d&#39;écriture (`app/page_builder/locales.py`) {#règles-décriture-apppage_builderlocalespy}&quot;">​</a></h3><ul><li>La langue d&#39;une page doit être servie par son site (<code>available_locales</code>, la langue par défaut comprise) : <strong>422 sur <code>locale</code></strong> (<code>FormValidationError</code>, une erreur par champ). Sa forme passe par <code>normalize_locale</code> (<code>app/content/i18n.py</code>), la seule définition d&#39;une langue valide du dépôt.</li><li>Une page a la langue de son parent, à la création comme à un changement de parent : <strong>422 sur <code>parent_id</code></strong>.</li><li>Une page se désigne par <code>(site, langue, slug)</code>. <strong>Toutes les routes par slug</strong> — lecture, rendu, modification, suppression, transitions, journal, accès (<code>/access</code>, <code>/access/preview</code>), détachement, éligibilité à l&#39;impression, points d&#39;un bloc, vote d&#39;utilité, traductions — prennent un paramètre de requête <code>locale</code> <strong>facultatif</strong>, défaut la langue par défaut du site : un appelant qui ignore les langues travaille comme avant sur celle-ci.</li></ul><h3 id="routes-du-back-office" tabindex="-1">Routes du back-office <a class="header-anchor" href="#routes-du-back-office" aria-label="Permalink to &quot;Routes du back-office {#routes-du-back-office}&quot;">​</a></h3><ul><li><code>GET /pages?site_id=…&amp;locale=…</code> : <code>locale</code> facultatif ; sans lui, <strong>toutes</strong> les langues, chaque ligne portant sa <code>locale</code>.</li><li><code>POST /pages</code> : <code>locale</code> facultatif dans le corps.</li><li><code>PageOut</code> gagne <code>locale</code> et <code>translation_group_id</code>.</li><li><code>POST /pages/{slug}/translations?site_id=…&amp;locale=&lt;source&gt;</code>, corps <code>{&quot;locale&quot;: &quot;en&quot;, &quot;slug&quot;?, &quot;title&quot;?}</code> → <strong>201</strong> <code>PageOut</code> de la nouvelle version, sous <code>page.write</code>. Elle naît <strong>par le même service que <code>POST /pages</code></strong> (<code>create_page</code>), donc sous les mêmes contrôles (unicité, conflit de préfixe ou de segment de langue, composition revalidée, médias, parent, services tiers) ; en brouillon ; dans le groupe de la source (créé à la première traduction, la source y entre alors — après les contrôles, pour qu&#39;un refus ne laisse pas un groupe d&#39;un seul membre) ; sous la version cible du parent de la source si elle existe, à la racine sinon. Composition, chapô, surtitre, image et SEO sont copiés ; titre et slug repris sauf s&#39;ils sont fournis. <strong>409</strong> « la version anglaise existe déjà » ; <strong>422 sur <code>locale</code></strong> pour une langue hors du site ou celle de la source.</li><li><code>GET /pages/{slug}/translations?site_id=…&amp;locale=…</code> → <code>[{id, locale, slug, title, status}]</code> triés par langue, la page comprise (<code>[elle-même]</code> sans groupe). Lue par qui voit les pages non publiées (<code>PAGE_PREVIEW_PERMISSIONS</code>, comme le journal) : elle nomme des brouillons.</li></ul><h3 id="public" tabindex="-1">Public <a class="header-anchor" href="#public" aria-label="Permalink to &quot;Public {#public}&quot;">​</a></h3><ul><li><strong>Adresse d&#39;une page</strong> : segment de sa langue (absent pour la langue par défaut, ADR-0034 règle 3) + chemin des slugs de ses ancêtres, de la même langue par construction (<code>page_path</code>, <code>app/content/urls.py</code>). Les pages existantes gardent exactement leur adresse.</li><li><code>GET /public/resolve</code> : le premier segment, s&#39;il est un segment de langue du site, choisit l&#39;arbre ; la page est cherchée dans cette langue (étape 1), et une page « déplacée » (étape 3) ne l&#39;est que dans la même langue. <strong><code>/en</code> et <code>/en/</code></strong> servent la version <code>en</code> du groupe de la page d&#39;accueil réglée, publiée et visible (même ACL, même 404 qu&#39;une racine sans accueil) ; son adresse propre (<code>/en/home</code>) redirige vers <code>/en</code>. Cette décision <strong>remplace la décision 5 de l&#39;ADR-0064</strong> (« la racine d&#39;une autre langue répond 404 ») pour le cas où l&#39;accueil a une version dans cette langue ; sans elle, <code>/en</code> répond toujours 404. La réponse porte <code>locale</code> = langue de la page, et <code>seo.alternates</code> = ses versions <strong>publiées et visibles</strong> (toute la chaîne publiée, au sens strict même pour un aperçu de back-office, puis l&#39;ACL du visiteur), <code>[{hreflang, locale, path, url}]</code>, <code>x-default</code> sur la langue par défaut — même forme <strong>et même règle que pour une fiche</strong> : vide quand une seule version est visible, un <code>hreflang</code> qui ne nommerait que la page n&#39;apprenant rien à un moteur. Le chemin d&#39;une page d&#39;accueil y est la racine de sa langue (<code>/</code>, <code>/en</code>), dans le fil d&#39;Ariane aussi.</li><li><code>GET /public/site</code> gagne <code>home_paths</code> (<code>{&quot;fr&quot;: &quot;/&quot;, &quot;en&quot;: &quot;/en&quot;}</code>), seulement pour les langues dont l&#39;accueil est publié et lisible par un anonyme ; <code>home_path</code> et <code>home_page_id</code> restent ceux de la langue par défaut.</li><li><code>GET /sitemap?…&amp;locale=…</code> (arbre public) : défaut la langue par défaut, l&#39;arbre ne contient que les pages de cette langue ; la réponse dit sa <code>locale</code>. Les sœurs d&#39;une page sont de sa langue. Les chemins se préfixent côté front (<code>locale_segments</code>).</li><li><strong>Plan de site XML</strong> : les pages de toutes les langues servies, à leur chemin préfixé, avec leurs <code>xhtml:link hreflang</code> vers leurs versions <strong>annoncées</strong> (<code>x-default</code> compris), comme les fiches ; chaque version de l&#39;accueil à la racine de sa langue.</li><li><strong>Recherche</strong> : une page est indexée dans sa langue (<code>search_config_for_locale(page.locale)</code>), et le filtre de langue de la recherche s&#39;applique aux pages (sous-requête sur <code>pages.locale</code>) ; son chemin de résultat porte le préfixe de sa langue.</li></ul><h3 id="décisions-prises-au-delà-du-contrat-du-lot" tabindex="-1">Décisions prises au-delà du contrat du lot <a class="header-anchor" href="#décisions-prises-au-delà-du-contrat-du-lot" aria-label="Permalink to &quot;Décisions prises au-delà du contrat du lot {#décisions-prises-au-delà-du-contrat-du-lot}&quot;">​</a></h3><ul><li><strong>La page d&#39;accueil désigne un groupe.</strong> Le réglage <code>sites.home_page_id</code> reste une seule page ; ses versions du même site sont les accueils des autres langues. <code>/</code> sert la version de la langue par défaut. Aucun nouveau refus n&#39;est ajouté à <code>PUT /sites/{id}/home-page</code> ; ses pages candidates portent désormais leur chemin préfixé de la langue.</li><li><strong>Page poussée vers un autre site</strong> (<code>POST /replication/pages/{id}/push</code>) : la copie <strong>garde sa langue</strong> et remplace la page de même slug <strong>dans cette langue</strong> ; si le site cible ne sert pas cette langue, <strong>refus nommé, 422 sur <code>locale</code></strong> — plutôt qu&#39;un repli silencieux sur la langue par défaut du site cible, qui servirait un texte anglais comme une page française. Le groupe de traduction ne voyage pas (ADR-0025 : une copie n&#39;est pas une version linguistique, et l&#39;unicité <code>(groupe, langue)</code> est globale).</li><li><strong>Usine à sites</strong> : le site provisionné <strong>reprend les langues de son modèle</strong> (<code>default_locale</code>, <code>available_locales</code>), si bien qu&#39;aucune page copiée n&#39;y est orpheline ; chaque copie garde sa langue, et les groupes de traduction sont <strong>recopiés avec un identifiant neuf</strong> sur le nouveau site — ses versions restent reliées entre elles, jamais à celles du modèle.</li><li><strong>Profils d&#39;usage</strong> : les pages de départ naissent dans la langue par défaut du site, par le même service (<code>create_page</code>), sans changement.</li><li><strong>Suppression</strong> : la tombe d&#39;une page supprimée (S15) est posée sur l&#39;adresse de sa langue (<code>/en/…</code> répond 410).</li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Une page, toutes ses langues dans <code>layout</code> (un sous-objet par langue)</strong></td><td>Écartée pour les raisons qui l&#39;ont fait écarter pour les contenus (ADR-0025) : un seul cycle de vie pour toutes les langues (publier l&#39;anglais publierait le français), une seule ligne d&#39;index de recherche, une seule configuration lexicale, et une validation de composition qui devrait connaître les langues.</td></tr><tr><td><strong>Un arbre unique, la langue portée par chaque page sans contrainte sur le parent</strong></td><td>Une page anglaise sous une rubrique française aurait une adresse mêlant deux langues, hériterait d&#39;une restriction d&#39;accès posée sur une page qu&#39;aucun visiteur anglais ne voit, et le plan du site d&#39;une langue montrerait des trous. Décision 2 du Product Owner.</td></tr><tr><td><strong>Traduction assistée par IA à la création</strong></td><td>Refusée par le Product Owner pour les pages : une composition se retraduit bloc par bloc, et un brouillon copié suffit à un traducteur.</td></tr><tr><td><strong>Clé étrangère <code>translation_group_id</code> → page source</strong></td><td>Même refus qu&#39;à l&#39;ADR-0025 (propriété 1) : supprimer la version française emporterait ou orphelinerait l&#39;anglaise.</td></tr><tr><td><strong>Push vers un site qui ne sert pas la langue : repli sur sa langue par défaut</strong></td><td>Servirait un texte dans une langue sous l&#39;étiquette d&#39;une autre (<code>&lt;html lang&gt;</code>, <code>hreflang</code>, dictionnaire de recherche faux). Un refus nommé se corrige en ajoutant la langue au site.</td></tr><tr><td><strong>Alternates d&#39;une page toujours non vides (la page seule)</strong></td><td>« Même forme que pour les fiches » : une fiche monolingue rend <code>[]</code>. Deux règles pour la même balise auraient divergé côté front.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Un site bilingue sert ses pages, son accueil (<code>/en</code>), son plan, son menu et sa recherche dans chaque langue, sans changer une seule adresse existante.</li><li>Les moteurs reçoivent les <code>hreflang</code> des pages comme ceux des fiches, dans la résolution et le plan XML.</li><li>Un appelant qui ignore les langues (ancien front, script) continue de fonctionner : <code>locale</code> est facultatif partout et vaut la langue par défaut.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Les routes par slug sans <code>locale</code> ne voient que la langue par défaut.</strong> Un client qui veut agir sur la version anglaise doit passer <code>locale=en</code> ; un relais du back-office qui l&#39;oublierait modifierait la version française.</li><li>Une traduction ne se resynchronise jamais depuis sa source, et — contrairement aux contenus — aucun indicateur de fraîcheur n&#39;existe encore pour les pages : une composition française corrigée ne signale rien côté anglais.</li><li>La résolution d&#39;une page traduite charge la chaîne de chaque membre du groupe pour les <code>alternates</code> : une requête par langue servie, bornée par le nombre de langues du site.</li><li>Le retour arrière de la migration 0050 exige d&#39;abord de supprimer toute version hors de la langue par défaut.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Modèle, migration 0050 (aller-retour <code>upgrade head</code> / <code>downgrade 0049</code> / <code>upgrade head</code> passé le 07/10/2026), routes du back-office (<code>locale</code> sur les routes par slug, <code>POST</code>/<code>GET /pages/{slug}/translations</code>), résolution <code>/en/…</code> et <code>/en</code>, <code>alternates</code>, <code>home_paths</code>, <code>GET /sitemap?locale</code>, plan XML avec <code>hreflang</code>, recherche par langue, usine à sites et poussée entre sites. Preuve : <code>tests/test_pages_multilingues.py</code> (12 tests verts ; les 12 échouent sur le code de <code>HEAD</code>).</li><li>[x] Back-office : langue dans la liste et la fiche d&#39;une page, encart « Versions linguistiques », bouton « Traduire en … », sélecteur de langue à la création (lot 12, partie admin) — fait : <code>apps/admin/pages/pages/index.vue</code>, <code>nouveau.vue</code>, <code>[slug]/index.vue</code>, relais <code>server/api/pages/[slug]/translations.{get,post}.ts</code>, validateur <code>optionalLocale</code> ; lint, typecheck et build verts.</li><li>[x] Front de démarrage : langue courante par segment, <code>&lt;html lang&gt;</code>, menu par langue, sélecteur de langue accessible, <code>&lt;link rel=&quot;alternate&quot; hreflang&gt;</code> (lot 12, partie front) — fait : voir la case de l&#39;ADR-0025 ; vitest 52 tests, axe sans violation.</li><li>[ ] Indicateur de fraîcheur des traductions de pages, sur le modèle de celui des contenus (ADR-0025).</li></ul>',26)])])}const m=a(t,[["render",r]]);export{p as __pageData,m as default};
